/// @sort 32
uniform Texture2D Source;
/// @sort 32
uniform float3 V = float3(1.0, 2.0, 3.0);
// The 1.x shorthands: `UE.SceneTexture(Id = ...)`, `SampleTexture2D(Tex, UV)`, `BreakOutFloat3Components(v, Output = "G")`.
/// @name M_LpShorthands
export void M_LpShorthands(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float Alpha = 0;
    float3 Scene = UE.Expression(Class = "SceneTexture", SceneTextureId = PPI_SceneColor)[0].rgb;
    float3 Texel = UE.Expression(Class = "TextureSample", TextureObject = Source, Coordinates = UE.TexCoord(Index = 0)).rgb;
    Alpha = V.g;
    Color = Scene + Texel;
    Base.EmissiveColor = Color;
    Base.Opacity = Alpha;
}
